//refAssemblies: TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Project Zomboid loads a Workshop item only when its numeric id is in WorkshopItems= and the
// ids from its mod.info files are in Mods= (both semicolon-separated, in servertest.ini).
string fileId = Convert.ToString(Dynamic.FileId);
string installPath = Convert.ToString(Dynamic.InstallPath);
string iniPath = Path.Combine(ThisService.RootDirectory, "Zomboid", "Server", "servertest.ini");

// mod.info "require=" entries are written as \ModId in Build 42; the server's Mods= list takes bare ids.
string Normalize(string entry) => entry.Trim().TrimStart('\\');

// One entry per mod id in a Workshop item. Build 41 items keep mods\<Mod>\mod.info, Build 42 items
// keep mods\<Mod>\42\mod.info, and many keep both; the Build 42 file wins for the requirements.
List<(string Id, List<string> Requires)> ReadMods(string itemPath)
{
    var mods = new List<(string Id, List<string> Requires, bool IsB42)>();
    string modsDir = Path.Combine(itemPath ?? string.Empty, "mods");
    if (!Directory.Exists(modsDir)) return new List<(string, List<string>)>();
    foreach (var info in Directory.EnumerateFiles(modsDir, "mod.info", SearchOption.AllDirectories).OrderBy(p => p, StringComparer.OrdinalIgnoreCase))
    {
        string id = null;
        var requires = new List<string>();
        foreach (var raw in File.ReadLines(info))
        {
            string line = raw.Trim();
            if (line.StartsWith("id=", StringComparison.OrdinalIgnoreCase)) id = line.Substring(3).Trim();
            else if (line.StartsWith("require=", StringComparison.OrdinalIgnoreCase))
                requires.AddRange(line.Substring(8).Split(',').Select(Normalize).Where(x => x.Length > 0));
        }
        if (string.IsNullOrEmpty(id)) continue;
        bool isB42 = Path.GetFileName(Path.GetDirectoryName(info)).StartsWith("42", StringComparison.Ordinal);
        int existing = mods.FindIndex(m => m.Id == id);
        if (existing < 0) mods.Add((id, requires, isB42));
        else if (isB42 && !mods[existing].IsB42) mods[existing] = (id, requires, true);
    }
    return mods.Select(m => (m.Id, m.Requires)).ToList();
}

List<string> SplitList(string value) =>
    (value ?? string.Empty).Split(';').Select(x => x.Trim()).Where(x => x.Length > 0).ToList();

string AddEntries(string value, IEnumerable<string> entries)
{
    var list = SplitList(value);
    foreach (var e in entries)
        if (!list.Any(x => Normalize(x) == Normalize(e))) list.Add(e);
    return string.Join(";", list);
}

string RemoveEntries(string value, IEnumerable<string> entries)
{
    var drop = new HashSet<string>(entries.Select(Normalize), StringComparer.Ordinal);
    return string.Join(";", SplitList(value).Where(x => !drop.Contains(Normalize(x))));
}

string SetIniValue(string text, string key, string value)
{
    var rx = new Regex("(?m)^" + Regex.Escape(key) + "=[^\\r\\n]*");
    if (rx.IsMatch(text)) return rx.Replace(text, key + "=" + value.Replace("$", "$$"), 1);
    string nl = text.Contains("\r\n") ? "\r\n" : "\n";
    return text.TrimEnd('\r', '\n') + nl + key + "=" + value + nl;
}

// The live ini is what the server reads; the service variables back the config editor fields
// and the file template, so both are kept in step.
async Task SaveLists(Func<string, string> workshop, Func<string, string> mods)
{
    var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
    var current = service.Variables ?? new TCAdminVars();
    string text = File.Exists(iniPath) ? await File.ReadAllTextAsync(iniPath, ThisCancellationToken) : null;
    // The ini wins when it exists: an owner may have edited it by hand since the variables were saved.
    string oldWorkshop = text != null ? Regex.Match(text, @"(?m)^WorkshopItems=([^\r\n]*)").Groups[1].Value : current.Parse<string>("WorkshopItems", string.Empty);
    string oldMods = text != null ? Regex.Match(text, @"(?m)^Mods=([^\r\n]*)").Groups[1].Value : current.Parse<string>("Mods", string.Empty);
    string newWorkshop = workshop(oldWorkshop);
    string newMods = mods(oldMods);

    if (text != null)
    {
        text = SetIniValue(text, "WorkshopItems", newWorkshop);
        text = SetIniValue(text, "Mods", newMods);
        await File.WriteAllTextAsync(iniPath, text, ThisCancellationToken);
    }

    var updated = new TCAdminVars();
    foreach (var pair in current) updated[pair.Key] = pair.Value;
    updated["WorkshopItems"] = newWorkshop;
    updated["Mods"] = newMods;
    service.Variables = updated;
    GameServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
    await GameServiceManager.SaveChangesAsync(ThisCancellationToken);

    ScriptConsole.WriteLine((object)("WorkshopItems=" + newWorkshop));
    ScriptConsole.WriteLine((object)("Mods=" + newMods));
}

var itemMods = ReadMods(installPath);
if (itemMods.Count == 0)
    ScriptConsole.WriteLine((object)$"Workshop item {fileId} has no mod.info files. Only WorkshopItems is updated.");

// Every mod id available on this server: the Workshop items downloaded so far, this one included.
string contentDir = Path.GetDirectoryName(installPath);
var available = new HashSet<string>(StringComparer.Ordinal);
if (Directory.Exists(contentDir))
    foreach (var item in Directory.GetDirectories(contentDir))
        foreach (var m in ReadMods(item)) available.Add(m.Id);

// Items often bundle optional sub-mods for other mods (map packs, UI frameworks). Enable only the
// ones whose requirements are installed; the server skips the rest with a warning anyway.
var pending = itemMods.Where(m => m.Requires.All(available.Contains)).ToList();
foreach (var skipped in itemMods.Where(m => !pending.Contains(m)))
    ScriptConsole.WriteLine((object)$"Not enabling {skipped.Id}: it needs {string.Join(", ", skipped.Requires.Where(r => !available.Contains(r)))}, which is not installed. Add it to Mods after installing that.");

// Requirements first, so Mods= reads in load order.
var enable = new List<string>();
while (pending.Count > 0)
{
    int next = pending.FindIndex(m => m.Requires.All(r => enable.Contains(r) || !pending.Any(p => p.Id == r)));
    if (next < 0) next = 0;
    enable.Add(pending[next].Id);
    pending.RemoveAt(next);
}
if (enable.Count > 0)
    ScriptConsole.WriteLine((object)$"Workshop item {fileId}: enabling {string.Join(", ", enable)}");

await SaveLists(
    w => AddEntries(w, new[] { fileId }),
    m => AddEntries(m, enable));
ScriptConsole.WriteLine((object)"The mod is loaded the next time the server starts.");

